import io.eezo.generated.Routes
import io.eezo.http.HttpApp
import io.eezo.http.RouteTable

/** The route table is generated by the sbt-eezo plugin from the files under `app/`: the file name
  * is the path and the `def` of the same name is the handler. `HttpApp` brings `main`, so `sbt run`
  * serves on port 8080.
  */
object Main extends HttpApp {
  override def routes: RouteTable = Routes.table()
}
